def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for m, o in history:
        if m == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1

    my_last, opp_last = history[-1]

    last_my_def = -1
    for i in range(n-1, -1, -1):
        if history[i][0] == 'D':
            last_my_def = i
            break

    last_outcome = None
    if last_my_def != -1 and last_my_def + 1 < n:
        if history[last_my_def + 1][1] == 'C':
            last_outcome = 'forgiven'
        else:
            last_outcome = 'retaliated'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_def <= max(1, n // 10) or opp_def <= n // 2:
                return 'C'
            return 'D'
        else:
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'

    if my_last == 'D':
        return 'C'

    if last_outcome == 'forgiven':
        if opp_def == 0:
            cooldown = 1
        else:
            cooldown = 5
    elif last_outcome == 'retaliated':
        cooldown = 20
    else:
        cooldown = 10

    if last_my_def == -1:
        if n >= cooldown:
            return 'D'
    else:
        if n - 1 - last_my_def >= cooldown:
            return 'D'

    return 'C'
